// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Myproject {
    struct Owner {
        address add;
        string name;
        string location;
        uint number;
    }
    struct Workers {
        address add;
        string name;
        string location;
        uint number;
    }
    struct Product {
        address add;
        string id;
        string typ;
    }
    address admin;
    Owner[] owner;
    Product[] product;
    Workers[] worker;
    mapping(address => Owner) addressToOwner;
    mapping(address => Workers) addressToWorker;
    mapping(address => Product) addressToProduct;

    constructor() {
        admin = msg.sender;
    }

    function addOwner(
        address _add,
        string memory _name,
        string memory _location,
        uint _num
    ) public {
        require(
            msg.sender == admin,
            "You are not the Admin. You cannot add any Owner"
        );
        Owner memory own = Owner({
            add: _add,
            name: _name,
            location: _location,
            number: _num
        });
        owner.push(own);
        addressToOwner[_add] = own;
    }

    function addWorkers(
        address _add,
        string memory _name,
        string memory _location,
        uint _num
    ) public {
        require(msg.sender == admin, "You are not the Admin");
        Workers memory work = Workers({
            add: _add,
            name: _name,
            location: _location,
            number: _num
        });
        worker.push(work);
        addressToWorker[_add] = work;
    }

    function AddProducts(
        address _add,
        string memory _id,
        string memory _typ
    ) public {
        Product memory prod = Product({add: _add, id: _id, typ: _typ});
        product.push(prod);
        addressToProduct[_add] = prod;
    }

    function getOwner(address _add) public view returns (Owner memory) {
        return addressToOwner[_add];
    }

    function getWorkers(address _add) public view returns (Workers memory) {
        return addressToWorker[_add];
    }

    function getProduct(address _add) public view returns (Product memory) {
        return addressToProduct[_add];
    }
    // remove owner and worker function product
}
